export interface TransformOptions {
    /**
     * Local bounding-box anchor in continuous [-1, 1] range per axis.
     * Mapped linearly across the entity's AABB via `getBoundaryPoint()`.
     *
     * - `[0, 0, 0]` (or `CENTER`, `ORIGIN`) → bounding-box center
     * - `[0, 1, 0]` (or `UP`) → top edge center
     * - `[-1, -1, 0]` (or `DL`) → bottom-left corner
     * - `[0, 0.5, 0]` → halfway between center and top edge
     */
    anchor?: Vec3Type;

    /**
     * Absolute World Space coordinate point.
     * Transforms occur directly around this scene position.
     *
     * - `[0, 0, 0]` → world origin
     * - `[20, 20, 0]` → specific world coordinate
     */
    pivot?: Vec3Type;
}

/**
 * Accepts either a bare Vec3Type anchor (shorthand for `{ anchor: vec }`)
 * or an explicit `TransformOptions` object.
 */
export type TransformOption = Vec3Type | TransformOptions;

/** Type guard to distinguish TransformOptions from Vec3Type vectors/arrays. */
export function isOptions(val: any): val is TransformOptions {
    return typeof val === 'object' && val !== null && !('x' in val) && !('length' in val);
}

private resolveTargetPivot(options?: TransformOption): Vec3 | undefined {
    if (!options) return undefined;
    if (isOptions(options)) {
        if (options.pivot !== undefined) return Vec3.cast(options.pivot);
        if (options.anchor !== undefined) return this.resolveLocalAnchor(options.anchor);
        return undefined;
    }
    return this.resolveLocalAnchor(options);
}

private resolveLocalAnchor(anchor: Vec3Type): Vec3 {
    const localAABB = this.getLocalAABB();
    const localPt = localAABB.getBoundaryPoint(anchor);

    const wt = this.getWorldTransform();
    const offsetMat = Mat4.translation(wt.offset);
    return wt.matrix.mul(offsetMat).transformPoint(localPt);
}

