public syncOffset(newOffset: Vec3Type): Transform {
    const offset_new = Vec3.cast(newOffset);
    const diff = this.offset.sub(offset_new);
    const worldShift = this._matrix.transformVector(diff);

    this.offset = offset_new;
    this._matrix.translateWorld(worldShift, this._matrix);
    this.UPDATE_FLAG = true;
    return this;
}

public setPivot(anchorWorld: Vec3Type): Transform {
    const A = Vec3.cast(anchorWorld);
    const invM = this._matrix.inverse();
    const V_anchor = invM.transformPoint(A).sub(this.offset);
    const offset_new = new Vec3(-V_anchor.x, -V_anchor.y, -V_anchor.z);
    return this.syncOffset(offset_new);
}

