private withPivot(options: TransformOption | undefined, fn: () => void): void {
    const oldOffset = this.anim.target.transform.offset.clone();
    const pivot = this.resolveTargetPivot(options);
    if (pivot) this.anim.target.transform.setPivot(pivot);
    fn();
    this.syncPivot(oldOffset);
}

private syncPivot(oldOffset: Vec3): void {
    const newOffset = this.anim.target.transform.offset;
    if (!oldOffset.equalsApprox(newOffset)) {
        this.anim.start.transform.syncOffset(newOffset);
        this.entity.transform.syncOffset(newOffset);
    }
}

// Align bottom-left corner to [0, 0, 0]
rect.move([0, 0, 0], DL);

// Align halfway between center and top edge to [10, 20, 0]
rect.move([10, 20, 0], [0, 0.5, 0]);

// Explicit options syntax
rect.move([10, 20, 0], { anchor: [0, 0.5, 0] });

// Rotate around entity's own bottom-left corner
rect.rotate(Math.PI / 4, DL);

// Rotate around continuous local anchor
rect.rotate(Math.PI / 4, { anchor: [0, 0.5, 0] });

// Rotate around specific world coordinate [25, 0, 0]
rect.rotate(Math.PI / 4, { pivot: [25, 0, 0] });

// Animate rotation around top edge
await scene.play(
    rect.animate.rotate(Math.PI, UP)
);

// Animate scale around world coordinate
await scene.play(
    rect.animate.scale(2.0, { pivot: [0, 0, 0] })
);

// Animate group rotation around group center
await scene.play(
    vgroup.animate.rotate(Math.PI / 2, CENTER)
);
